      { id: "da_e9", question: "Which metric represents the difference between the maximum and minimum values in a dataset?", options: ["Variance", "Interquartile Range", "Range", "Standard Deviation"], answer: 2, explanation: "Range = Maximum - Minimum, providing a quick but outlier-sensitive measure of total span." },
      { id: "da_e10", question: "What does ETL stand for in modern enterprise data pipelines?", options: ["Enterprise Tech Logic", "Extract, Transform, Load", "Evaluate, Train, Learn", "Execute, Test, Launch"], answer: 1, explanation: "ETL extracts raw data from operational sources, transforms and cleans it, and loads it into a data warehouse." }
