      { id: "iot_m10", question: "How do MQTT wildcard subscriptions work with '+' (single-level) and '#' (multi-level)?", options: ["'+' matches all characters; '#' matches numbers only", "'+' matches exactly one topic hierarchy level (e.g. sensor/+/temp); '#' matches all remaining sub-levels hierarchically (e.g. sensor/#)", "They are identical wildcard operators", "'+' matches from start; '#' matches from end"], answer: 1, explanation: "Single-level '+' matches one token between slashes; multi-level '#' must be at the end, capturing all arbitrary subtopics." }
